     {onboardingStep===2&&<><span className="eyebrow"><Heart size={15}/> {profile.uiLanguage==='he'?'נעים להכיר':profile.uiLanguage==='es'?'ENCANTADO DE CONOCERTE':profile.uiLanguage==='fr'?'RAVI DE TE RENCONTRER':profile.uiLanguage==='de'?'SCHÖN, DICH KENNENZULERNEN':profile.uiLanguage==='pt'?'PRAZER EM CONHECER VOCÊ':profile.uiLanguage==='it'?'PIACERE DI CONOSCERTI':profile.uiLanguage==='ja'?'はじめまして':profile.uiLanguage==='ko'?'만나서 반가워요':profile.uiLanguage==='ar'?'سعيد بلقائك':'NICE TO MEET YOU'}</span><h1>{t('yourName')}</h1><p>{t('nameHint')}</p><input className="big-input" value={profile.name} maxLength={32} onChange={e=>setProfile(p=>({...p,name:e.target.value}))} onKeyDown={e=>e.key==='Enter'&&profile.name.trim()&&setOnboardingStep(3)} placeholder={t('namePlaceholder')} autoFocus/><button className="cta" disabled={!profile.name.trim()} onClick={()=>{const next={...profile,uiLanguage:chosenUi};setProfile(next);try{localStorage.setItem('codequest-profile-v3',JSON.stringify(next));}catch{}setOnboardingStep(3);}}>{t('continue')} <ChevronRight size={20}/></button></>}
     {onboardingStep===3&&<><span className="eyebrow"><Code2 size={15}/> {profile.uiLanguage==='he'?'בחרו את כוח-העל שלכם':profile.uiLanguage==='es'?'ELIGE TU SUPERPODER':profile.uiLanguage==='fr'?'CHOISIS TON SUPER-POUVOIR':profile.uiLanguage==='de'?'WÄHLE DEINE SUPERKRAFT':profile.uiLanguage==='pt'?'ESCOLHA SEU SUPERPODER':profile.uiLanguage==='it'?'SCEGLI IL TUO SUPERPOTERE':profile.uiLanguage==='ja'?'得意技を選ぼう':profile.uiLanguage==='ko'?'나만의 능력을 선택해요':profile.uiLanguage==='ar'?'اختر قوتك الخارقة':'PICK YOUR SUPERPOWER'}</span><h1>{t('learnTitle')}</h1><p>{t('learnHint')}</p><div className="course-select-grid">{courses.map(c=><button key={c.name} className={'course-select '+(chosenCourses.includes(c.name)?'picked':'')} style={{'--course-color':c.color} as React.CSSProperties} onClick={()=>setChosenCourses(prev=>prev.includes(c.name)?prev.filter(n=>n!==c.name):[...prev,c.name])}><span className="course-emoji">{c.icon}</span><span>{c.name}</span>{chosenCourses.includes(c.name)&&<Check size={16}/>}</button>)}</div><button className="cta" disabled={!chosenCourses.length} onClick={()=>setOnboardingStep(4)}>{t('continue')} <ChevronRight size={20}/></button></>}
     {onboardingStep===4&&<><span className="eyebrow"><Brain size={15}/> PERSONALIZED PATH</span><h1>{t('experienceTitle')}</h1><p>{t('experienceHint')}</p><div className="experience-options">{expValues.map((v,i)=><button key={v} className={'experience-option '+(chosenExperience===v?'picked':'')} onClick={()=>setChosenExperience(v)}><span className="exp-number">{['🌱','🌿','🌳','🚀'][i]}</span><span><b>{t(v)}</b><small>{['We start from zero','A few things look familiar','I can read simple code','Challenge me a little more'][i]}</small></span><span className="radio-dot"/></button>)}</div><button className="cta" onClick={()=>void finishOnboarding()}>{t('start')} <Rocket size={19}/></button></>}
